const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const query = String(payload.query || payload.rawText || payload.text || '').trim();
const limit = Math.max(1, Math.min(8, Number(payload.limit || 5) || 5));
const threshold = Math.max(0, Math.min(1, Number(payload.threshold || 0.45) || 0.45));
const memoryType = String(payload.memory_type || payload.memoryType || '').trim();
if (!chatId) {
  throw new Error('Missing chatId for memory_search');
}
if (!query) {
  return [{ json: { chatId, query: '', skip: true, responseText: 'MEMORY_SEARCH_RESULTS\nnone' } }];
}
return [{ json: { chatId, query, limit, threshold, memoryType, skip: false } }];

