const prepared = $('Prepare Memory Search').item.json || {};
if (prepared.skip) {
  return [{ json: { skip: true, responseText: prepared.responseText, chatId: prepared.chatId || '' } }];
}
const response = $('Embed Search Query').item.json || {};
const vector = Array.isArray(response.embeddings) && response.embeddings[0] ? response.embeddings[0] : null;
if (!vector) {
  throw new Error('No embedding returned for memory_search query');
}
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
const vectorLiteral = `[${vector.map((value) => Number(value).toFixed(8)).join(',')}]`;
const q = escapeSql(prepared.query);
const filterType = prepared.memoryType ? ` AND i.memory_type = '${escapeSql(prepared.memoryType)}'` : '';
const sql = `WITH semantic AS ( SELECT c.chunk_text, c.chunk_index, i.memory_type, i.title, i.tags, i.importance, i.created_at, 1 - (c.embedding <=> '${vectorLiteral}'::vector) AS semantic_score, (CASE WHEN c.chunk_text ILIKE '%${q}%' THEN 0.12 ELSE 0 END + CASE WHEN i.title ILIKE '%${q}%' THEN 0.08 ELSE 0 END + CASE WHEN array_to_string(i.tags, ' ') ILIKE '%${q}%' THEN 0.05 ELSE 0 END) AS keyword_bonus FROM mia_memory_chunks c JOIN mia_memory_items i ON i.id = c.item_id WHERE c.chat_id = '${escapeSql(prepared.chatId)}' AND i.is_active = true${filterType} ORDER BY c.embedding <=> '${vectorLiteral}'::vector LIMIT ${Math.max(prepared.limit * 4, 8)} ) SELECT chunk_text, chunk_index, memory_type, title, tags, importance, created_at, semantic_score, keyword_bonus, semantic_score + keyword_bonus AS final_score FROM semantic WHERE semantic_score >= ${prepared.threshold} OR keyword_bonus > 0 ORDER BY final_score DESC, importance DESC, created_at DESC LIMIT ${prepared.limit};`;
return [{ json: { chatId: prepared.chatId, query: prepared.query, sql } }];

const prepared = $('Prepare Memory Search').item.json || {};
if (prepared.skip) {
  return [{ json: { text: prepared.responseText, chatId: prepared.chatId || '', result: { items: [] } } }];
}
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.chunk_text);
if (rows.length === 0) {
  return [{ json: { text: `MEMORY_SEARCH_RESULTS\nquery: ${prepared.query}\nnone`, chatId: prepared.chatId || '', result: { items: [] } } }];
}
const items = rows.map((row) => ({
  memory_type: row.memory_type || 'general',
  title: row.title || '',
  chunk_text: row.chunk_text || '',
  chunk_index: row.chunk_index ?? null,
  tags: Array.isArray(row.tags) ? row.tags : [],
  importance: row.importance || 3,
  created_at: row.created_at || null,
  semantic_score: Number(row.semantic_score || 0),
  keyword_bonus: Number(row.keyword_bonus || 0),
  final_score: Number(row.final_score || row.semantic_score || 0)
}));
const lines = ['MEMORY_SEARCH_RESULTS', `query: ${prepared.query}`];
items.forEach((item, index) => {
  const score = Number(item.final_score || 0).toFixed(4);
  const title = item.title ? ` | title=${item.title}` : '';
  const tags = item.tags.length ? ` | tags=${item.tags.join(', ')}` : '';
  lines.push(`${index + 1}. [${item.memory_type}] score=${score}${title}${tags}`);
  lines.push(`content: ${item.chunk_text}`);
});
return [{ json: { text: lines.join('\n'), chatId: prepared.chatId || '', result: { items } } }];
